// Six source examples were Qurʾānic but lacked the structured metadata needed
// by the quotation renderer and Qurʾānic-only filter.
const addPrintedQuranCitation=(id,enCitation,arCitation)=>{
 const item=auditedExercise(id);
 item.sourceEn=item.sourceEn.replace(/(printed page [^.]+\.)/u,`$1 ${enCitation}`);
 item.sourceAr=item.sourceAr.replace(/(الْمَطْبُوعَةُ [٠-٩–-]+\.)/u,`$1 ${arCitation}`);
};
addPrintedQuranCitation('noun-07','Qur’an 2:259.','سُورَةُ الْبَقَرَةِ، الْآيَةُ ٢٥٩.');
addPrintedQuranCitation('noun-08','Qur’an 16:27.','سُورَةُ النَّحْلِ، الْآيَةُ ٢٧.');
addPrintedQuranCitation('noun-10','Qur’an 15:65.','سُورَةُ الْحِجْرِ، الْآيَةُ ٦٥.');
addPrintedQuranCitation('verb-16','Qur’an 2:233.','سُورَةُ الْبَقَرَةِ، الْآيَةُ ٢٣٣.');
{
 const item=auditedExercise('khafd-01');
 item.sourceEn=item.sourceEn.replace(/(printed page 43\.)/u,'$1 Qur’an 1:1. The app uses Medina numbering; this verse attribution is app-supplied because the edition prints no sūrah/āyah reference here.');
 item.sourceAr=item.sourceAr.replace(/(الْمَطْبُوعَةُ ٤٣\.)/u,'$1 سُورَةُ الْفَاتِحَةِ، الْآيَةُ ١. وَيَسْتَعْمِلُ التَّطْبِيقُ تَرْقِيمَ مُصْحَفِ الْمَدِينَةِ؛ وَنِسْبَةُ الْآيَةِ مِنَ التَّطْبِيقِ لِأَنَّ الطَّبْعَةَ لَا تَذْكُرُ مَرْجِعًا هُنَا.');
}

// Final shibh-jumlah predicate normalization. The source distinguishes a
// word's own government from the construction-level khabar relationship.
// These overrides run after every earlier content audit so the student-facing
// answers consistently name the shibh jumlah and its exact predicate owner.
setAuditedAnswerAt('noun-08',1,'أَيْنَ','اسْمُ اسْتِفْهَامٍ مَبْنِيٌّ عَلَى الْفَتْحِ فِي مَحَلِّ نَصْبٍ ظَرْفُ مَكَانٍ. وَالظَّرْفُ شِبْهُ جُمْلَةٍ، مُتَعَلِّقٌ بِخَبَرٍ مُقَدَّمٍ مَحْذُوفٍ لِلْمُبْتَدَإِ الْمُؤَخَّرِ «شُرَكَائِيَ».','Ayna is an interrogative noun built on fatḥ, in the accusative position as an adverb of place. The adverbial shibh jumlah is attached to an omitted fronted predicate of the delayed mubtadaʾ shurakāʾiya.');
setAuditedAnswerAt('raf-06',2,'آيَاتِهِ','«آيَاتِ» اسْمٌ مَجْرُورٌ بِـ«مِنْ»، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ، وَهُوَ مُضَافٌ. وَالْهَاءُ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى الْكَسْرِ فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ. وَالْجَارُّ وَالْمَجْرُورُ شِبْهُ جُمْلَةٍ، مُتَعَلِّقَانِ بِخَبَرٍ مُقَدَّمٍ مَحْذُوفٍ لِلْمُبْتَدَإِ الْمُؤَخَّرِ «الْجَوَارِ».','Āyāti is governed by min, genitive with a visible kasrah, and is the first term of an iḍāfah. Hāʾ is an attached pronoun in the genitive position as its second term. The prepositional phrase is a shibh jumlah attached to an omitted fronted predicate of the delayed mubtadaʾ al-jawāri.');
setAuditedAnswerAt('raf-12',3,'مِنْكُمْ','«مِنْ» حَرْفُ جَرٍّ مَبْنِيٌّ عَلَى السُّكُونِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَالْكَافُ ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى الضَّمِّ فِي مَحَلِّ جَرٍّ بِـ«مِنْ»، وَالْمِيمُ عَلَامَةُ الْجَمْعِ. وَالْجَارُّ وَالْمَجْرُورُ شِبْهُ جُمْلَةٍ، مُتَعَلِّقَانِ بِخَبَرِ «يَكُنْ» الْمُقَدَّمِ الْمَحْذُوفِ، وَاسْمُهَا الْمُؤَخَّرُ «عِشْرُونَ».','Min is a preposition; kāf is an attached pronoun built on ḍamm in the genitive position after min, and mīm marks plurality. The prepositional phrase is a shibh jumlah attached to the omitted fronted predicate of yakun; its delayed ism is ʿishrūna.');
setAuditedAnswerAt('khafd-02',3,'هُدًى','«هُدًى» اسْمٌ مَجْرُورٌ بِـ«عَلَى»، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الْمُقَدَّرَةُ عَلَى الْأَلِفِ لِلتَّعَذُّرِ. وَالْجَارُّ وَالْمَجْرُورُ شِبْهُ جُمْلَةٍ، مُتَعَلِّقَانِ بِخَبَرٍ مَحْذُوفٍ لِلْمُبْتَدَإِ «أُولَئِكَ».','Hudā is governed by ʿalā, genitive with an estimated kasrah on the alif. The prepositional phrase is a shibh jumlah attached to an omitted predicate of the mubtadaʾ ulāʾika.');
setAuditedAnswerAt('khafd-03',1,'لِلرِّجَالِ','اللَّامُ حَرْفُ جَرٍّ مَبْنِيٌّ عَلَى الْكَسْرِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَ«الرِّجَالِ» اسْمٌ مَجْرُورٌ بِاللَّامِ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ. وَالْجَارُّ وَالْمَجْرُورُ شِبْهُ جُمْلَةٍ، مُتَعَلِّقَانِ بِخَبَرٍ مُقَدَّمٍ مَحْذُوفٍ لِلْمُبْتَدَإِ الْمُؤَخَّرِ «نَصِيبٌ».','Lām is a preposition, and al-rijāli is governed by it, genitive with a visible kasrah. The prepositional phrase is a shibh jumlah attached to an omitted fronted predicate of the delayed mubtadaʾ naṣībun.');
setAuditedPartsAt('relative-01',2,'لِلَّهِ',[
 {ar:'اللَّامُ حَرْفُ جَرٍّ مَبْنِيٌّ عَلَى الْكَسْرِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.',en:'Lām is a preposition built on kasrah, with no syntactic position.'},
 {ar:'«اللَّهِ» اسْمٌ مَجْرُورٌ بِاللَّامِ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ. وَالْجَارُّ وَالْمَجْرُورُ شِبْهُ جُمْلَةٍ، مُتَعَلِّقَانِ بِخَبَرٍ مَحْذُوفٍ لِلْمُبْتَدَإِ «الْحَمْدُ».',en:'Allāhi is governed by lām, genitive with a visible kasrah. The prepositional phrase is a shibh jumlah attached to an omitted predicate of the mubtadaʾ al-ḥamdu.'}
]);
setAuditedPartsAt('relative-10',1,'فَمِنْهُمْ',[
 {ar:'الْفَاءُ حَرْفُ عَطْفٍ مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ، وَ«مِنْ» حَرْفُ جَرٍّ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.',en:'Fāʾ is a conjunction built on fatḥ with no syntactic position; min is a preposition built on sukūn with no syntactic position.'},
 {ar:'«هُمْ» ضَمِيرٌ مُتَّصِلٌ مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ جَرٍّ بِـ«مِنْ». وَالْجَارُّ وَالْمَجْرُورُ شِبْهُ جُمْلَةٍ، مُتَعَلِّقَانِ بِخَبَرٍ مُقَدَّمٍ مَحْذُوفٍ لِلْمُبْتَدَإِ الْمُؤَخَّرِ «مَنْ».',en:'Hum is an attached pronoun built on sukūn in the genitive position after min. The prepositional phrase is a shibh jumlah attached to an omitted fronted predicate of the delayed mubtadaʾ man.'}
]);
setAuditedAnswerAt('article-01',2,'زُجَاجَةٍ','«زُجَاجَةٍ» اسْمٌ مَجْرُورٌ بِـ«فِي»، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ. وَالْجَارُّ وَالْمَجْرُورُ شِبْهُ جُمْلَةٍ، مُتَعَلِّقَانِ بِخَبَرٍ مَحْذُوفٍ لِلْمُبْتَدَإِ السَّابِقِ فِي سِيَاقِ الْآيَةِ «الْمِصْبَاحُ».','Zujājatin is governed by fī, genitive with a visible kasrah. The prepositional phrase is a shibh jumlah attached to an omitted predicate of the preceding mubtadaʾ al-miṣbāḥu in the verse context.');
setAuditedAnswerAt('article-02',4,'الْغَارِ','«الْغَارِ» اسْمٌ مَجْرُورٌ بِـ«فِي»، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ. وَالْجَارُّ وَالْمَجْرُورُ شِبْهُ جُمْلَةٍ، مُتَعَلِّقَانِ بِخَبَرٍ مَحْذُوفٍ لِلْمُبْتَدَإِ «هُمَا».','Al-ghāri is governed by fī, genitive with a visible kasrah. The prepositional phrase is a shibh jumlah attached to an omitted predicate of the mubtadaʾ humā.');
