const releaseBook=(id,page,ar,en,tokens,directEn='The source prints this example, and its note or footnote supplies the stated rule or core parsing.',directAr='يَطْبَعُ الْمَصْدَرُ هَذَا الْمِثَالَ، وَيَذْكُرُ نَصُّهُ أَوْ حَاشِيَتُهُ الْقَاعِدَةَ أَوْ أَصْلَ الْإِعْرَابِ.')=>exercise(id,page,ar,en,tokens,directEn,directAr);
const releaseQuran=(id,page,ar,en,tokens,surahNumber,ayah,surahAr,directEn='The source prints this exact Qurʾānic excerpt, and its footnote supplies the core parsing.',directAr='يَطْبَعُ الْمَصْدَرُ هَذَا الْمَقْطَعَ الْقُرْآنِيَّ بِحَدِّهِ، وَتَذْكُرُ حَاشِيَتُهُ أَصْلَ الْإِعْرَابِ.')=>exercise(id,page,ar,en,tokens,`Qur’an ${surahNumber}:${ayah}. ${directEn}`,`سُورَةُ ${surahAr}، الْآيَةُ ${String(ayah).replace(/\d/g,d=>'٠١٢٣٤٥٦٧٨٩'[d])}. ${directAr}`);
const laysaParticle=(word,gloss)=>token(word,gloss,'حَرْفُ نَفْيٍ يَعْمَلُ عَمَلَ «لَيْسَ»، مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.','Negative particle operating like laysa, built on sukūn with no syntactic position.');
const laysaGovernorEn=governor=>({'مَا':'mā','لَا':'lā','إِنْ':'in'}[governor]||governor);
const laysaIsm=(word,gloss,governor)=>token(word,gloss,`اسْمُ «${governor}» مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.`,`Ism of ${laysaGovernorEn(governor)}, nominative with a visible ḍammah.`);
const laysaKhabar=(word,gloss,governor)=>token(word,gloss,`خَبَرُ «${governor}» مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.`,`Khabar of ${laysaGovernorEn(governor)}, accusative with a visible fatḥah.`);

