const muqPast=(word,gloss)=>word.endsWith('ى')
 ?token(word,gloss,'فِعْلٌ مَاضٍ نَاقِصٌ مِنْ أَفْعَالِ الْمُقَارَبَةِ، مَبْنِيٌّ عَلَى الْفَتْحِ الْمُقَدَّرِ عَلَى الْأَلِفِ لِلتَّعَذُّرِ.','Deficient past verb of proximity, built on a fatḥ estimated on the final alif.')
 :token(word,gloss,'فِعْلٌ مَاضٍ نَاقِصٌ مِنْ أَفْعَالِ الْمُقَارَبَةِ، مَبْنِيٌّ عَلَى الْفَتْحِ.','Deficient past verb of proximity, built on fatḥ.');
const muqGovernorEn=governor=>({'كَادَ':'kāda','يَكَادُ':'yakādu','كَرَبَ':'karaba','أَوْشَكَ':'awshaka','عَسَى':'ʿasā','حَرَى':'ḥarā','اخْلَوْلَقَ':'ikhlawlaqa','اخْلَوْلَقَتْ':'ikhlawlaqat','طَفِقَ':'ṭafiqa','عَلِقَ':'ʿaliqa','أَنْشَأَ':'anshaʾa','أَخَذَ':'akhadha','جَعَلَ':'jaʿala','يُوشِكُ':'yūshiku'}[governor]||governor);
const muqIsm=(word,gloss,governor)=>token(word,gloss,`اسْمُ «${governor}» مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.`,`Ism of ${muqGovernorEn(governor)}, nominative with a visible ḍammah.`);
const muqPresent=(word,gloss,governor,subject='هُوَ',subjectEn='he')=>token(word,gloss,`فِعْلٌ مُضَارِعٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ، وَفَاعِلُهُ ضَمِيرٌ مُسْتَتِرٌ جَوَازًا تَقْدِيرُهُ ${subject}، وَجُمْلَةُ الْفِعْلِ وَالْفَاعِلِ فِي مَحَلِّ نَصْبٍ خَبَرُ «${governor}».`,`Present verb, indicative with a visible ḍammah; its hidden subject is “${subjectEn}.” The verbal clause is in the accusative position as the khabar of ${muqGovernorEn(governor)}.`);
const muqAn=(verb,gloss,governor,subject='هُوَ',subjectEn='he')=>[
 token('أَنْ','to','حَرْفُ مَصْدَرٍ وَنَصْبٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.','Subordinating and subjunctive particle built on sukūn with no syntactic position.'),
 token(verb,gloss,`فِعْلٌ مُضَارِعٌ مَنْصُوبٌ بِـ«أَنْ»، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ، وَفَاعِلُهُ ضَمِيرٌ مُسْتَتِرٌ جَوَازًا تَقْدِيرُهُ ${subject}، وَالْمَصْدَرُ الْمُنْسَبِكُ مِنْ «أَنْ» وَالْفِعْلِ فِي مَحَلِّ نَصْبٍ خَبَرُ «${governor}».`,`Present verb made subjunctive by an, marked by a visible fatḥah; its hidden subject is “${subjectEn}.” The interpreted verbal noun is in the accusative position as the khabar of ${muqGovernorEn(governor)}.`)
];

