const release3Quran=(id,page,ar,en,tokens,surahNumber,ayah,surahAr,directEn='The source prints this exact Qurʾānic excerpt, and its footnote supplies the core parsing.',directAr='يَطْبَعُ الْمَصْدَرُ هَذَا الْمَقْطَعَ الْقُرْآنِيَّ بِحَدِّهِ، وَتَذْكُرُ حَاشِيَتُهُ أَصْلَ الْإِعْرَابِ.')=>releaseQuran(id,page,ar,en,tokens,surahNumber,ayah,surahAr,directEn,directAr);
const release3QuranRange=(id,page,ar,en,tokens,surahNumber,ayah,ayahEnd,surahAr,directEn,directAr)=>exercise(id,page,ar,en,tokens,`Qur’an ${surahNumber}:${ayah}–${ayahEnd}. ${directEn}`,`سُورَةُ ${surahAr}، الْآيَاتُ ${String(ayah).replace(/\d/g,d=>'٠١٢٣٤٥٦٧٨٩'[d])}–${String(ayahEnd).replace(/\d/g,d=>'٠١٢٣٤٥٦٧٨٩'[d])}. ${directAr}`);
const innaParticle=(word,gloss,labelAr='تَوْكِيدٍ وَنَصْبٍ',labelEn='emphasis and accusative government')=>token(word,gloss,`حَرْفُ ${labelAr} يَنْصِبُ الِاسْمَ وَيَرْفَعُ الْخَبَرَ، مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.`,`Particle of ${labelEn}; it makes the ism accusative and the khabar nominative, and is built on fatḥ with no syntactic position.`);
const innaIsm=(word,gloss,governor='إِنَّ')=>token(word,gloss,`اسْمُ «${governor}» مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.`,`Ism of ${governor==='إِنَّ'?'inna':governor}, accusative with a visible fatḥah.`);
const innaKhabar=(word,gloss,governor='إِنَّ')=>token(word,gloss,`خَبَرُ «${governor}» مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.`,`Khabar of ${governor==='إِنَّ'?'inna':governor}, nominative with a visible ḍammah.`);
